package com.example.starter.domain;

/**
 * 列车作业状态：ACCEPTED 接入；CHECKED 编组核对通过；DEPARTURE_CONFIRMED 发车确认；CLOSED 销记终态。
 */
public enum JobStatus {
    ACCEPTED,
    CHECKED,
    DEPARTURE_CONFIRMED,
    CLOSED
}

package com.example.starter.domain;

/**
 * 制动试验类型：SENSITIVITY 感度试验（减压 50kPa 全列须制动）；STABILITY 安定试验（减压 140kPa 不得紧急制动）。
 */
public enum TestType {
    SENSITIVITY,
    STABILITY
}

package com.example.starter.domain;

/**
 * 试验/核对结论：PASS 合格，FAIL 不合格。
 */
public enum TestResult {
    PASS,
    FAIL
}

package com.example.starter.service;

import org.springframework.http.HttpStatus;

/**
 * 业务异常基类，携带 HTTP 状态码，由全局异常处理器转换为统一错误响应。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;

    public ApiException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus getStatus() {
        return status;
    }
}

package com.example.starter.service;

import org.springframework.http.HttpStatus;

/**
 * 冲突异常（HTTP 409）：幂等键同键异参、同一股道并发接入唯一受理冲突等。
 */
public class ConflictException extends ApiException {

    public ConflictException(String message) {
        super(HttpStatus.CONFLICT, message);
    }
}

package com.example.starter.service;

import org.springframework.http.HttpStatus;

/**
 * 业务规则拒绝异常（HTTP 422）：运统1核对不一致拒绝发车、风压未恢复定压、流程状态不允许等。
 */
public class BusinessException extends ApiException {

    public BusinessException(String message) {
        super(HttpStatus.UNPROCESSABLE_ENTITY, message);
    }
}

package com.example.starter.service;

import org.springframework.http.HttpStatus;

/**
 * 资源不存在异常（HTTP 404）：作业不存在等。
 */
public class NotFoundException extends ApiException {

    public NotFoundException(String message) {
        super(HttpStatus.NOT_FOUND, message);
    }
}

