package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

import java.math.BigDecimal;

/**
 * 车辆信息（合成数据）。
 *
 * @param carNo       车辆号
 * @param weightTons  重量，单位吨
 * @param length      换长
 * @param valveClosed 是否关门车
 */
public record CarDto(
        @NotBlank String carNo,
        @NotNull @PositiveOrZero BigDecimal weightTons,
        @NotNull @PositiveOrZero BigDecimal length,
        boolean valveClosed) {
}

package com.example.starter.web.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;

import java.util.List;

/**
 * 列车接入请求。
 *
 * @param requestId 幂等请求键
 * @param trainNo   车次（合成数据）
 * @param track     股道号
 * @param cars      编组车辆清单
 */
public record AcceptJobRequest(
        @NotBlank String requestId,
        @NotBlank String trainNo,
        @NotBlank String track,
        @NotEmpty List<@Valid CarDto> cars) {
}

package com.example.starter.web.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.util.List;

/**
 * 摘挂变更请求；变更与试验结论作废在同一事务内完成。
 *
 * @param requestId    幂等请求键
 * @param attachCars   挂车清单（可为空列表）
 * @param detachCarNos 摘车车辆号清单（可为空列表）
 */
public record ConsistChangeRequest(
        @NotBlank String requestId,
        @NotNull List<@Valid CarDto> attachCars,
        @NotNull List<String> detachCarNos) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

import java.math.BigDecimal;

/**
 * 编组核对请求，携带合成运统1数据。
 *
 * @param requestId           幂等请求键
 * @param expectedCarCount    运统1辆数
 * @param expectedTotalLength 运统1换长
 * @param expectedTotalWeight 运统1总重，单位吨
 */
public record ConsistCheckRequest(
        @NotBlank String requestId,
        @NotNull @PositiveOrZero Integer expectedCarCount,
        @NotNull @PositiveOrZero BigDecimal expectedTotalLength,
        @NotNull @PositiveOrZero BigDecimal expectedTotalWeight) {
}

package com.example.starter.web.dto;

import com.example.starter.domain.TestType;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

/**
 * 制动试验请求。
 *
 * @param requestId          幂等请求键
 * @param testType           试验类型：SENSITIVITY 感度 / STABILITY 安定
 * @param pressureReduction  减压量，单位 kPa
 * @param pipePressureBefore 试验前列车管风压，单位 kPa；须恢复至定压 500kPa（恰达允许）
 * @param allCarsBraked      感度试验：全列是否均制动
 * @param emergencyOccurred  安定试验：是否发生紧急制动
 */
public record BrakeTestRequest(
        @NotBlank String requestId,
        @NotNull TestType testType,
        @NotNull @PositiveOrZero Integer pressureReduction,
        @NotNull @PositiveOrZero Integer pipePressureBefore,
        Boolean allCarsBraked,
        Boolean emergencyOccurred) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 仅含幂等键的请求（发车确认、销记）。
 *
 * @param requestId 幂等请求键
 */
public record RequestIdOnly(
        @NotBlank String requestId) {
}

